# Before: Base R error handling
validate_input &lt;- function(x, y) {
  if (!is.numeric(x)) {
    stop("x must be numeric")
  }
  if (length(y) == 0) {
    stop("y cannot be empty")
  }
  if (length(x) != length(y)) {
    stop("x and y must have the same length")
  }
}

# After: CLI error handling
validate_input &lt;- function(x, y) {
  if (!is.numeric(x)) {
    cli_abort(c(
      "{.arg x} must be numeric",
      "x" = "You supplied a {.cls {class(x)}} vector",
      "i" = "Use {.fn as.numeric} to convert"
    ))
  }

  if (length(y) == 0) {
    cli_abort(c(
      "{.arg y} cannot be empty",
      "i" = "Provide at least one element"
    ))
  }

  if (length(x) != length(y)) {
    cli_abort(c(
      "{.arg x} and {.arg y} must have the same length",
      "x" = "{.arg x} has length {length(x)}",
      "x" = "{.arg y} has length {length(y)}"
    ))
  }
}



check_required_columns &lt;- function(data, required_cols) {
  actual_cols &lt;- names(data)
  missing_cols &lt;- setdiff(required_cols, actual_cols)

  if (length(missing_cols) &gt; 0) {
    cli_abort(c(
      "Required column{?s} missing from data",
      "x" = "Missing {length(missing_cols)} column{?s}: {.field {missing_cols}}",
      "i" = "Data has {length(actual_cols)} column{?s}: {.field {actual_cols}}",
      "i" = "Add the missing column{?s} or check for typos"
    ))
  }

  invisible(data)
}



process_files &lt;- function(files, verbose = TRUE) {
  n &lt;- length(files)

  if (verbose) {
    cli_progress_bar(
      format = "Processing {cli::pb_bar} {cli::pb_current}/{cli::pb_total} [{cli::pb_eta}]",
      total = n
    )
  }

  results &lt;- vector("list", n)

  for (i in seq_along(files)) {
    results[[i]] &lt;- process_file(files[[i]])

    if (verbose) {
      cli_progress_update()
    }
  }

  results
}

Grep the rendered files or run the automated reference checker (python3 scripts/check-rendered-references.py &lt;output-dir&gt;). ?@ is the primary signal; -F keeps ? literal:
# Automated scanner (handles crossrefs, citations, and ignores valid footnotes)
python3 scripts/check-rendered-references.py &lt;output-dir&gt;

# Primary: unresolved cross-references (and Quarto's unresolved-citation marker)
grep -rnoF --include='*.html' '?@' &lt;output-dir&gt;

# Secondary heuristic: missing citation key rendered bold with a trailing ?
# (the **key?** marker becomes &lt;strong&gt;key?&lt;/strong&gt; in HTML, so the greps
# above miss it)
grep -rnoE --include='*.html' '&lt;strong&gt;[A-Za-z0-9_:.#-]+\?&lt;/strong&gt;' &lt;output-dir&gt;

# Secondary heuristic: raw citation syntax left in the body
grep -rnoE --include='*.html' '\[-?@[A-Za-z0-9_:.#-]+' &lt;output-dir&gt;
For each ?@… hit, pull the surrounding text so the report is actionable:
grep -rnE --include='*.html' '.{0,40}\?@[A-Za-z0-9_:.#-]+.{0,40}' &lt;output-dir&gt;
Also covers PDF/docx when those are the rendered output — for PDF, extract text first (pdftotext file.pdf - | grep -nF '?@'); a broken crossref shows as ?@key there too.

